	end

TrainerTower_8F_EventScript_DoublesTrainer2::
	call TrainerTower_EventScript_SpeakToDoublesTrainer2
	end

TrainerTower_8F_EventScript_Owner::
	call TrainerTower_EventScript_SpeakToOwner
	end
