FourIsland_House2_EventScript_BragLinkWinsHigh::
	goto_if_eq VAR_LINK_WIN_BRAG_STATE, 3, FourIsland_House2_EventScript_AlreadyBraggedLinkWins
	setvar VAR_LINK_WIN_BRAG_STATE, 3
